import{_ as s,o as a,c as p,a2 as e}from"./chunks/framework.CNQbXYGB.js";const t="/dcu-microarch-guide/assets/dcu_note_fig1.BgXb7QL-.png",g=JSON.parse('{"title":"第 1 章：DCU 整体架构、执行模型与软件栈链路","description":"","frontmatter":{},"headers":[],"relativePath":"01-overview/software-stack.md","filePath":"01-overview/software-stack.md"}'),l={name:"01-overview/software-stack.md"};function o(c,n,i,r,d,h){return a(),p("div",null,[...n[0]||(n[0]=[e('<h1 id="第-1-章-dcu-整体架构、执行模型与软件栈链路" tabindex="-1">第 1 章：DCU 整体架构、执行模型与软件栈链路 <a class="header-anchor" href="#第-1-章-dcu-整体架构、执行模型与软件栈链路" aria-label="Permalink to &quot;第 1 章：DCU 整体架构、执行模型与软件栈链路&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">小白速读：先用大白话理解这一章</p><p>把 GPU 想象成一家<strong>大型物流+工厂园区</strong>：<strong>Grid</strong> 是整张生产订单，<strong>Block（Workgroup）</strong> 是一个车间小组，<strong>CU</strong> 是物理车间，<strong>Wavefront（64 个线程）</strong> 是车间里必须“喊同一个口令齐步走”的 64 人方阵。我们在 Python 里写一行 <code>torch.matmul</code>，会依次穿过 PyTorch → 算子库/Triton → HIP → HSA 队列，最后由 DCU 的总调度台（CP）把一个个车间小组派发到 64 个 CU 里干活。</p></div><h2 id="一、gpu-的整体硬件结构与执行层级" tabindex="-1">一、GPU 的整体硬件结构与执行层级 <a class="header-anchor" href="#一、gpu-的整体硬件结构与执行层级" aria-label="Permalink to &quot;一、GPU 的整体硬件结构与执行层级&quot;">​</a></h2><p>理解 DCU 微架构，首先要区分两个概念：</p><ul><li><strong>软件执行模型：</strong> 程序员如何组织线程、划分计算任务。</li><li><strong>硬件执行架构：</strong> GPU 如何分配计算资源、调度线程、执行指令和搬运数据。</li></ul><p>二者相互关联，但不是简单的一一对应关系。</p><h3 id="_1-1-软件执行模型" tabindex="-1">1.1 软件执行模型 <a class="header-anchor" href="#_1-1-软件执行模型" aria-label="Permalink to &quot;1.1 软件执行模型&quot;">​</a></h3><p><img src="'+t+`" alt="从软件执行层级到 CU 的计算资源映射（图文笔记图 1）"></p><p>在 HIP 编程中，一次 Kernel 启动会形成一个 Grid，Grid 包含多个 Block（Workgroup），每个 Block 内包含多个 Thread（Work-item）。</p><p>以 Wavefront Size 为 64、Block Size 为 256 为例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kernel Launch</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Grid</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── Block 0（256 Threads）</span></span>
<span class="line"><span>    │   ├── Wavefront 0（Thread 0～63）</span></span>
<span class="line"><span>    │   ├── Wavefront 1（Thread 64～127）</span></span>
<span class="line"><span>    │   ├── Wavefront 2（Thread 128～191）</span></span>
<span class="line"><span>    │   └── Wavefront 3（Thread 192～255）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── Block 1（256 Threads）</span></span>
<span class="line"><span>    │   └── 4 个 Wavefront</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── Block N</span></span>
<span class="line"><span>        └── 4 个 Wavefront</span></span></code></pre></div><p>各层级的职责如下：</p><table tabindex="0"><thead><tr><th>概念</th><th>主要作用</th><th>与硬件的关系</th></tr></thead><tbody><tr><td>Grid</td><td>组织一次 Kernel 的全部计算任务</td><td>分布到整张 GPU 的多个 CU</td></tr><tr><td>Block / Workgroup</td><td>组织可以共享数据并同步的线程</td><td>一个 Block 被分配到一个 CU</td></tr><tr><td>Wavefront</td><td>一组共享指令执行流的线程</td><td>GPU 的重要调度与执行单位</td></tr><tr><td>Thread / Work-item</td><td>负责具体数据元素的计算</td><td>对应 Wavefront 中的逻辑 Lane</td></tr><tr><td>Lane</td><td>Thread 在当前 Wavefront 内的位置</td><td>用于指令执行、数据布局及跨 Lane 通信</td></tr></tbody></table><p>需要注意，Grid、Block、Wavefront、Thread 是描述程序执行的概念，并不是四种独立的物理计算单元。</p><h3 id="_1-2-dcu-的物理硬件组织" tabindex="-1">1.2 DCU 的物理硬件组织 <a class="header-anchor" href="#_1-2-dcu-的物理硬件组织" aria-label="Permalink to &quot;1.2 DCU 的物理硬件组织&quot;">​</a></h3><p>以早期 z100 类微架构为例，可以建立如下整体认知：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DCU GPU</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 命令处理与任务分发</span></span>
<span class="line"><span>│   ├── 接收 Kernel Dispatch</span></span>
<span class="line"><span>│   ├── 管理计算任务</span></span>
<span class="line"><span>│   └── 将 Workgroup 分配给 CU</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Compute Unit 0</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── 调度与控制单元</span></span>
<span class="line"><span>│   │   ├── Wavefront Scheduler</span></span>
<span class="line"><span>│   │   ├── 指令发射与依赖管理</span></span>
<span class="line"><span>│   │   └── 分支与执行掩码控制</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── Scalar 执行资源</span></span>
<span class="line"><span>│   │   ├── SALU</span></span>
<span class="line"><span>│   │   └── SGPR</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── Vector 执行资源</span></span>
<span class="line"><span>│   │   ├── SIMD 0 + VGPR</span></span>
<span class="line"><span>│   │   ├── SIMD 1 + VGPR</span></span>
<span class="line"><span>│   │   ├── SIMD 2 + VGPR</span></span>
<span class="line"><span>│   │   └── SIMD 3 + VGPR</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── 矩阵计算资源</span></span>
<span class="line"><span>│   │   └── MMAC / 矩阵乘加指令路径</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── LDS（片上共享存储）</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   └── 访存接口与近端 Cache</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Compute Unit 1</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Compute Unit N</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── GPU 片上互连与共享 L2 Cache</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Memory Controller</span></span>
<span class="line"><span>    └── HBM / 全局显存</span></span></code></pre></div><p>这是一张<strong>逻辑功能结构图</strong>，不是具体芯片的物理布局图。</p><p>例如矩阵计算资源可能与 SIMD/向量执行资源存在复杂的共享关系；L1、L2 的实际组织与共享范围也因芯片代际而不同。</p><p>图中 z100 的部分特性，包括每 CU 四组 SIMD、Wave64 和 CU 内共享 LDS，可以作为学习起点，但不能直接推断所有 BW 系列采用完全相同的组织方式。</p><h3 id="_1-3-从-pytorch-到-dcu-硬件的软件栈链路" tabindex="-1">1.3 从 PyTorch 到 DCU 硬件的软件栈链路 <a class="header-anchor" href="#_1-3-从-pytorch-到-dcu-硬件的软件栈链路" aria-label="Permalink to &quot;1.3 从 PyTorch 到 DCU 硬件的软件栈链路&quot;">​</a></h3><p>参考 <code>hello-rocm</code> 中“解密 AI 加速器（decode-ai-accelerator）”的视角，在实际大模型推理/训练中，一条算子调用是如何穿透软件栈到达上述物理硬件的？</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PyTorch / vLLM / SGLang（计算图与调度）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── 通用数学库：rocBLAS / hipBLAS / MIOpen</span></span>
<span class="line"><span>        ├── 高级融合算子库：lightop / aiter / deepgemm</span></span>
<span class="line"><span>        └── DSL 编译器：Triton（Python → TTIR → TTGIR → LLVM IR → AMDGCN ISA）</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        HIP / DTK Runtime（hipLaunchKernelGGL / Stream / Event）</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        HSA Runtime（用户态队列 AQL Packet、内存管理与信号量）</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        Kernel Driver（KFD / 硬件驱动提交门铃 Doorbell）</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        DCU Command Processor (CP) → 分发 Workgroup 到各个 CU</span></span></code></pre></div><p>理解这条链路有三个直接价值：</p><ol><li><strong>定位“到底跑了谁的 Kernel”</strong>：在 PyTorch 中调用一次线性层或 RMSNorm，底层可能走 rocBLAS（<code>Cijk_...</code>）、Triton 生成的 <code>.hsaco</code>、或者 <code>lightop</code>/<code>aiter</code>/<code>deepgemm</code> 的手写/模板 Kernel，用 <code>torch.profiler</code> 或 <code>rocprof</code> 才能看清真实落点。</li><li><strong>理解 Triton 与手写 HIP 的映射关系</strong>：Triton 的 <code>tl.load</code> / <code>tl.dot</code> / <code>num_warps</code> / <code>num_stages</code> 并不是魔法，最终都会被 LLVM 后端编译为同样受 <strong>VGPR、LDS、<code>s_waitcnt</code> 和 MMAC</strong> 约束的设备端 ISA。</li><li><strong>追踪环境依赖</strong>：通过 <code>ldd</code> 或 Python 包路径检查 <code>torch</code> 链接的 <code>libamdhip64.so</code> / <code>libhsa-runtime64.so</code>，可以快速排查版本错配或算子回退问题。</li></ol><hr>`,26)])])}const m=s(l,[["render",o]]);export{g as __pageData,m as default};
